/* Host Mode demo: a pretend database that lives only in this browser, so anyone can try the app without touching real events. */
(function(){if(!/[?&]e=demo(&|$)/i.test(location.search))return;window.__HMDEMO=true;const KEY="hm_demo_db";const load=()=>{try{return JSON.parse(localStorage.getItem(KEY))||{}}catch(e){return {}}};let data=load();const listeners=[];
const split=p=>p.split("/").filter(Boolean);const clone=v=>v==null?null:JSON.parse(JSON.stringify(v));
const getAt=p=>{let o=data;for(const k of split(p)){if(o==null||typeof o!=="object")return null;o=o[k]}return o===undefined?null:clone(o)};
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(data))}catch(e){window.__saveErr=String(e)}};
const fixTs=v=>{if(v&&typeof v==='object'){if(v['.sv']==='timestamp')return Date.now();const o=Array.isArray(v)?[]:{};for(const k in v)o[k]=fixTs(v[k]);return o}return v};
const setAt=(p,v)=>{v=fixTs(v);data=load();const ks=split(p);if(!ks.length){data=clone(v)||{};}else{let o=data;for(const k of ks.slice(0,-1)){if(typeof o[k]!=="object"||o[k]==null)o[k]={};o=o[k]}if(v==null)delete o[ks.at(-1)];else o[ks.at(-1)]=clone(v)}save();listeners.forEach(l=>l.cb(snap(l.p)))};
const snap=p=>({val:()=>getAt(p),key:split(p).at(-1),exists:()=>getAt(p)!=null,forEach:f=>{const v=getAt(p)||{};Object.keys(v).forEach(k=>f({key:k,val:()=>v[k]}))}});
let pid=0;
class Ref{constructor(p){this.p=p||"";this.key=split(this.p).at(-1)}
 on(e,cb){if(e==='child_added'){const seen=new Set();const p=this.p;const fire=()=>{const v=getAt(p)||{};Object.keys(v).forEach(k=>{if(!seen.has(k)){seen.add(k);cb({key:k,val:()=>v[k]})}})};listeners.push({p,cb:()=>fire()});setTimeout(fire,0);return cb}if(this.p===".info/connected"){setTimeout(()=>cb({val:()=>true}),0);return cb}if(this.p===".info/serverTimeOffset"){cb({val:()=>0});return cb}listeners.push({p:this.p,cb});setTimeout(()=>cb(snap(this.p)),0);return cb}
 off(){} once(){return Promise.resolve(snap(this.p))}
 set(v){setAt(this.p,v);return Promise.resolve()} update(u){for(const k in u)setAt(this.p+"/"+k,u[k]);return Promise.resolve()} remove(){setAt(this.p,null);return Promise.resolve()}
 push(v){const k="k"+Date.now().toString(36)+(++pid);const r=new Ref(this.p+"/"+k);if(v!==undefined){setAt(r.p,v)}r.then=(a,b)=>Promise.resolve().then(a,b);return r}
 transaction(fn,done){/* like real Firebase: first run uses the local cache (null if nothing is listening), then the server value */
  const listened=listeners.some(l=>this.p===l.p||this.p.startsWith(l.p+"/"));const srv=getAt(this.p);let cur=listened?srv:null;
  for(let i=0;i<3;i++){const r2=fn(cur==null?null:JSON.parse(JSON.stringify(cur)));if(r2===undefined){const s=snap(this.p);done&&done(null,false,s);return Promise.resolve({committed:false,snapshot:s})}
   if(JSON.stringify(cur)===JSON.stringify(srv)){if(JSON.stringify(r2)!==JSON.stringify(srv))setAt(this.p,r2);const s=snap(this.p);setTimeout(()=>done&&done(null,true,snap(this.p)),5);return Promise.resolve({committed:true,snapshot:s})}cur=srv}
  done&&done(new Error("maxretry"),false);return Promise.resolve({committed:false})}
 child(c){return new Ref(this.p+"/"+c)} orderByChild(){return this} endAt(){return this} limitToLast(){return this} startAt(){return this} equalTo(){return this} limitToFirst(){return this}}
window.addEventListener('storage',e=>{if(e.key===KEY){data=load();listeners.forEach(l=>l.cb(snap(l.p)))}});
const db={ref:p=>new Ref(p),goOnline(){},goOffline(){}};
window.firebase={initializeApp(){},database:Object.assign(()=>db,{Reference:Ref,ServerValue:{TIMESTAMP:{'.sv':'timestamp'}}})};})();

window.HM_DEMO_PHOTOS=[{thumb:"data:image/jpeg;base64,",full:"data:image/jpeg;base64,"},{thumb:"data:image/jpeg;base64,",full:"data:image/jpeg;base64,"},{thumb:"data:image/jpeg;base64,",full:"data:image/jpeg;base64,"}];
